from copy import deepcopy
from collections.abc import Callable, Iterable, Mapping
from typing import Any


def extract_dataset(
    videos: Iterable[tuple[str, Iterable[Any]]],
    extractor: Callable[[Any], Any],
    actions: Mapping[tuple[int, int], str] | None = None,
) -> dict[str, list[object]]:
    action_map = {} if actions is None else actions
    result: dict[str, list[object]] = {}
    quitting = False
    for video_index, (label, frames) in enumerate(videos):
        if not isinstance(label, str) or not label:
            raise ValueError("labels must be non-empty strings")
        result.setdefault(label, [])
        for frame_index, frame in enumerate(frames):
            action = action_map.get((video_index, frame_index), "save")
            if action not in {"save", "skip", "quit"}:
                raise ValueError(f"unknown action: {action}")
            if action == "quit":
                quitting = True
                break
            if action == "skip":
                break
            sample = extractor(frame)
            if sample is not None:
                result[label].append(sample)
        if quitting:
            break
    return result

